{
  "name": "YatraAI - Smart India Travel Planner",
  "description": "A comprehensive AI-powered travel planner for India that calculates routes, budgets, stays, and sightseeing itineraries for any city or town."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum TransportMode {
  BUS = 'Bus',
  TRAIN = 'Train',
  FLIGHT = 'Flight',
  CAB = 'Cab'
}

export interface TransportOption {
  mode: TransportMode;
  providerName: string; // e.g., "Indigo", "Shatabdi Express", "Volvo AC"
  duration: string;
  cost: number;
  description: string;
}

export interface Place {
  name: string;
  category: 'Historical' | 'Nature' | 'Religious' | 'Adventure' | 'Leisure';
  distance: string; // distance from center/destination
  description: string;
  estimatedEntryCost: number;
}

export interface Stay {
  name: string;
  type: 'Hotel' | 'Hostel' | 'Resort' | 'Lodge';
  pricePerNight: number;
  rating: number;
  location: string;
  features: string[];
}

export interface TripPlan {
  source: string;
  destination: string;
  distanceKm: number;
  bestTimeToVisit: string;
  transportOptions: TransportOption[];
  placesToVisit: Place[];
  stayOptions: Stay[];
  estimatedFoodCostPerDay: number;
  localTravelCostEstimate: number;
  summary: string;
}

export interface UserInput {
  source: string;
  destination: string;
  travelers: number;
  days: number;
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { TripPlan } from "../types";

// In a real production app, ensure this is handled via a secure proxy or valid env var
const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

const tripPlanSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    source: { type: Type.STRING },
    destination: { type: Type.STRING },
    distanceKm: { type: Type.NUMBER, description: "Approximate distance in KM" },
    bestTimeToVisit: { type: Type.STRING },
    summary: { type: Type.STRING, description: "A short, inspiring summary of the trip" },
    transportOptions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          mode: { type: Type.STRING, enum: ["Bus", "Train", "Flight", "Cab"] },
          providerName: { type: Type.STRING },
          duration: { type: Type.STRING },
          cost: { type: Type.NUMBER, description: "Cost in INR per person" },
          description: { type: Type.STRING },
        },
        required: ["mode", "cost", "duration", "providerName"],
      },
    },
    placesToVisit: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          category: { type: Type.STRING, enum: ['Historical', 'Nature', 'Religious', 'Adventure', 'Leisure'] },
          distance: { type: Type.STRING, description: "Distance from main city center" },
          description: { type: Type.STRING },
          estimatedEntryCost: { type: Type.NUMBER, description: "Entry fee in INR" },
        },
        required: ["name", "category", "distance"],
      },
    },
    stayOptions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['Hotel', 'Hostel', 'Resort', 'Lodge'] },
          pricePerNight: { type: Type.NUMBER, description: "Cost in INR per night" },
          rating: { type: Type.NUMBER },
          location: { type: Type.STRING },
          features: { type: Type.ARRAY, items: { type: Type.STRING } },
        },
        required: ["name", "pricePerNight", "type"],
      },
    },
    estimatedFoodCostPerDay: { type: Type.NUMBER, description: "Average food cost per person per day in INR" },
    localTravelCostEstimate: { type: Type.NUMBER, description: "Estimated total local travel cost (cabs/autos) for the whole trip in INR" },
  },
  required: ["source", "destination", "transportOptions", "placesToVisit", "stayOptions", "estimatedFoodCostPerDay"],
};

export const generateTripPlan = async (source: string, destination: string, days: number): Promise<TripPlan> => {
  if (!API_KEY) {
    throw new Error("API Key is missing. Please check your environment configuration.");
  }

  const prompt = `
    Act as an expert Indian Travel Agent. Plan a detailed trip from ${source} to ${destination} for ${days} days.

    Requirements:
    1. Provide 3-4 distinct transport options (Cheapest, Fastest, Balanced).
    2. Suggest 6 top tourist places within 100km radius of ${destination}, categorized by type.
    3. Suggest 4 accommodation options ranging from budget hostels to comfort hotels.
    4. Estimate realistic costs in INR (Indian Rupees).
    5. Be specific about train names or flight routes if applicable (e.g., "Shatabdi Express", "Indigo via Delhi").

    Ensure the response is strictly valid JSON according to the schema.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", // Efficient for complex reasoning + JSON
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: tripPlanSchema,
        temperature: 0.4, // Lower temperature for more factual/realistic pricing
      },
    });

    const text = response.text;
    if (!text) throw new Error("No data received from AI");

    return JSON.parse(text) as TripPlan;
  } catch (error) {
    console.error("Error generating trip plan:", error);
    throw new Error("Failed to generate trip plan. Please try again.");
  }
};

import React, { useMemo } from 'react';
import { TripPlan, TransportOption, Stay } from '../types';
import { IndianRupee, PieChart } from 'lucide-react';

interface ExpenseCalculatorProps {
  plan: TripPlan;
  travelers: number;
  days: number;
  selectedTransport: TransportOption | null;
  selectedStay: Stay | null;
}

const ExpenseCalculator: React.FC<ExpenseCalculatorProps> = ({ 
  plan, 
  travelers, 
  days, 
  selectedTransport, 
  selectedStay 
}) => {

  // Defaults if nothing selected (take lowest/average for initial view)
  const transportCost = selectedTransport ? selectedTransport.cost : Math.min(...plan.transportOptions.map(t => t.cost));
  const stayCost = selectedStay ? selectedStay.pricePerNight : Math.min(...plan.stayOptions.map(s => s.pricePerNight));

  const totalTransport = transportCost * travelers * 2; // Round trip
  const totalStay = stayCost * days * Math.ceil(travelers / 2); // Assuming 2 people per room
  const totalFood = plan.estimatedFoodCostPerDay * days * travelers;
  const totalLocalTravel = plan.localTravelCostEstimate;
  const buffer = 2000; // Emergency buffer

  const grandTotal = totalTransport + totalStay + totalFood + totalLocalTravel + buffer;

  return (
    <div className="bg-white rounded-xl shadow-lg p-6 border border-slate-100 sticky top-6">
      <div className="flex items-center gap-2 mb-4 text-orange-600">
        <PieChart size={24} />
        <h2 className="text-xl font-bold">Estimated Budget</h2>
      </div>

      <div className="space-y-3 text-sm text-slate-600">
        <div className="flex justify-between items-center">
          <span>Travel (Round Trip) <span className="text-xs bg-slate-100 px-1 rounded">x{travelers}</span></span>
          <span className="font-medium">₹{totalTransport.toLocaleString()}</span>
        </div>

        <div className="flex justify-between items-center">
          <span>Stay ({days} Nights) <span className="text-xs bg-slate-100 px-1 rounded">{Math.ceil(travelers/2)} Rooms</span></span>
          <span className="font-medium">₹{totalStay.toLocaleString()}</span>
        </div>

        <div className="flex justify-between items-center">
          <span>Food & Drinks</span>
          <span className="font-medium">₹{totalFood.toLocaleString()}</span>
        </div>

        <div className="flex justify-between items-center">
          <span>Local Sightseeing</span>
          <span className="font-medium">₹{totalLocalTravel.toLocaleString()}</span>
        </div>

        <div className="flex justify-between items-center text-xs text-slate-400">
          <span>Misc/Buffer</span>
          <span>₹{buffer.toLocaleString()}</span>
        </div>
      </div>

      <div className="border-t border-slate-200 my-4 pt-4">
        <div className="flex justify-between items-end">
          <span className="text-slate-500 font-medium">Total Estimate</span>
          <div className="text-right">
             <span className="text-3xl font-bold text-slate-800 block leading-none">
              ₹{grandTotal.toLocaleString()}
             </span>
             <span className="text-xs text-slate-400">approx. for whole trip</span>
          </div>
        </div>
      </div>

      <div className="mt-4 bg-orange-50 p-3 rounded-lg text-xs text-orange-700">
        <strong>Tip:</strong> This is an estimate based on {selectedTransport ? 'selected' : 'cheapest'} travel and {selectedStay ? 'selected' : 'budget'} stay options.
      </div>
    </div>
  );
};

export default ExpenseCalculator;

import React from 'react';
import { TransportOption, TransportMode } from '../types';
import { Plane, Train, Bus, Car, Clock, ArrowRight } from 'lucide-react';

interface TransportCardProps {
  option: TransportOption;
  isSelected: boolean;
  onSelect: () => void;
}

const TransportCard: React.FC<TransportCardProps> = ({ option, isSelected, onSelect }) => {

  const getIcon = (mode: TransportMode) => {
    switch (mode) {
      case TransportMode.FLIGHT: return <Plane className="text-blue-500" />;
      case TransportMode.TRAIN: return <Train className="text-red-500" />;
      case TransportMode.BUS: return <Bus className="text-orange-500" />;
      case TransportMode.CAB: return <Car className="text-green-500" />;
      default: return <Bus />;
    }
  };

  return (
    <div 
      onClick={onSelect}
      className={`relative cursor-pointer transition-all duration-300 border rounded-xl p-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 ${
        isSelected ? 'border-orange-500 bg-orange-50 ring-1 ring-orange-500' : 'border-slate-200 bg-white hover:border-orange-300 hover:shadow-md'
      }`}
    >
      <div className="flex items-center gap-4">
        <div className="p-3 bg-white rounded-full shadow-sm border border-slate-100">
          {getIcon(option.mode)}
        </div>
        <div>
          <h4 className="font-semibold text-slate-800">{option.providerName}</h4>
          <p className="text-sm text-slate-500 line-clamp-1">{option.description}</p>
          <div className="flex items-center gap-1 mt-1 text-xs text-slate-400 font-medium">
             <Clock size={12} /> {option.duration} travel time
          </div>
        </div>
      </div>

      <div className="text-right w-full sm:w-auto flex flex-row sm:flex-col justify-between items-center sm:items-end">
        <div className="text-lg font-bold text-slate-800">₹{option.cost.toLocaleString()}</div>
        <div className={`text-xs px-2 py-1 rounded-full ${isSelected ? 'bg-orange-200 text-orange-800' : 'bg-slate-100 text-slate-500'}`}>
          per person
        </div>
      </div>

      {isSelected && (
        <div className="absolute -top-2 -right-2 bg-orange-500 text-white p-1 rounded-full shadow-sm">
          <ArrowRight size={14} />
        </div>
      )}
    </div>
  );
};

export default TransportCard;

import React, { useState } from 'react';
import { TripPlan, TransportOption, Stay } from './types';
import { generateTripPlan } from './services/geminiService';
import ExpenseCalculator from './components/ExpenseCalculator';
import TransportCard from './components/TransportCard';
import { MapPin, Calendar, Users, ArrowRight, Loader2, Info, Star, Map, Hotel, Navigation } from 'lucide-react';

const App: React.FC = () => {
  // Input State
  const [source, setSource] = useState('');
  const [destination, setDestination] = useState('');
  const [days, setDays] = useState<number>(3);
  const [travelers, setTravelers] = useState<number>(2);

  // App State
  const [loading, setLoading] = useState(false);
  const [plan, setPlan] = useState<TripPlan | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Selection State for Calculator
  const [selectedTransport, setSelectedTransport] = useState<TransportOption | null>(null);
  const [selectedStay, setSelectedStay] = useState<Stay | null>(null);

  // Future Scope Modal
  const [showScope, setShowScope] = useState(false);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!source || !destination) return;

    setLoading(true);
    setError(null);
    setPlan(null);

    try {
      const result = await generateTripPlan(source, destination, days);
      setPlan(result);
      // Set defaults for calculator
      if (result.transportOptions.length > 0) setSelectedTransport(result.transportOptions[0]);
      if (result.stayOptions.length > 0) setSelectedStay(result.stayOptions[0]);
    } catch (err: any) {
      setError(err.message || "Something went wrong.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 pb-20">
      {/* Navbar */}
      <nav className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center gap-2">
              <div className="bg-orange-500 p-2 rounded-lg text-white">
                <Navigation size={20} />
              </div>
              <span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-orange-600 to-red-600">
                YatraAI
              </span>
            </div>
            <button 
              onClick={() => setShowScope(true)}
              className="text-sm text-slate-500 hover:text-orange-600 font-medium"
            >
              Future & Scope
            </button>
          </div>
        </div>
      </nav>

      {/* Hero / Search Section */}
      <div className={`transition-all duration-500 ${plan ? 'bg-white border-b border-slate-200 py-6' : 'bg-gradient-to-br from-indigo-900 to-slate-900 py-20 text-white'}`}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          {!plan && (
            <div className="text-center mb-10">
              <h1 className="text-4xl sm:text-5xl font-extrabold mb-4 tracking-tight">
                Plan your perfect <span className="text-orange-500">India Trip</span> in seconds.
              </h1>
              <p className="text-slate-300 text-lg max-w-2xl mx-auto">
                AI-powered routes, budget estimation, and itinerary generation for every city, town, and village in India.
              </p>
            </div>
          )}

          <form onSubmit={handleSearch} className={`bg-white rounded-2xl shadow-xl p-4 sm:p-6 grid grid-cols-1 md:grid-cols-12 gap-4 items-end ${plan ? 'border border-slate-200' : ''}`}>
            <div className="md:col-span-3">
              <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">From</label>
              <div className="relative">
                <MapPin className="absolute left-3 top-3 text-slate-400" size={18} />
                <input
                  type="text"
                  placeholder="e.g. Delhi"
                  value={source}
                  onChange={(e) => setSource(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent outline-none text-slate-900"
                  required
                />
              </div>
            </div>

            <div className="hidden md:flex md:col-span-1 justify-center pb-3">
              <ArrowRight className="text-slate-300" />
            </div>

            <div className="md:col-span-3">
              <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">To</label>
              <div className="relative">
                <MapPin className="absolute left-3 top-3 text-slate-400" size={18} />
                <input
                  type="text"
                  placeholder="e.g. Manali"
                  value={destination}
                  onChange={(e) => setDestination(e.target.value)}
                  className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent outline-none text-slate-900"
                  required
                />
              </div>
            </div>

            <div className="md:col-span-2">
              <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">Duration</label>
              <div className="relative">
                <Calendar className="absolute left-3 top-3 text-slate-400" size={18} />
                <select 
                  value={days}
                  onChange={(e) => setDays(Number(e.target.value))}
                  className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent outline-none text-slate-900 appearance-none"
                >
                  {[2,3,4,5,7,10,14].map(d => <option key={d} value={d}>{d} Days</option>)}
                </select>
              </div>
            </div>

            <div className="md:col-span-1">
               <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">Travelers</label>
               <div className="relative">
                  <Users className="absolute left-3 top-3 text-slate-400" size={18} />
                  <input
                    type="number"
                    min="1"
                    max="20"
                    value={travelers}
                    onChange={(e) => setTravelers(Number(e.target.value))}
                    className="w-full pl-10 pr-2 py-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent outline-none text-slate-900"
                  />
               </div>
            </div>

            <div className="md:col-span-2">
              <button
                type="submit"
                disabled={loading}
                className="w-full bg-orange-600 hover:bg-orange-700 text-white font-bold py-3 px-6 rounded-lg transition-colors flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
              >
                {loading ? <><Loader2 className="animate-spin" size={20} /> Planning...</> : 'Plan Trip'}
              </button>
            </div>
          </form>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-8">

        {/* Error State */}
        {error && (
          <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded-r shadow-sm mb-8">
            <div className="flex items-center">
              <Info className="text-red-500 mr-2" />
              <p className="text-red-700">{error}</p>
            </div>
          </div>
        )}

        {/* Results */}
        {plan && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

            {/* Left Column: Itinerary Details */}
            <div className="lg:col-span-2 space-y-8">

              {/* Trip Header */}
              <div>
                <h2 className="text-3xl font-bold text-slate-900 mb-2">Trip to {plan.destination}</h2>
                <div className="flex flex-wrap gap-3 text-sm text-slate-600">
                   <span className="bg-white border px-3 py-1 rounded-full">{plan.distanceKm} km away</span>
                   <span className="bg-white border px-3 py-1 rounded-full">Best time: {plan.bestTimeToVisit}</span>
                </div>
                <p className="mt-4 text-slate-600 leading-relaxed bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
                  {plan.summary}
                </p>
              </div>

              {/* Transport Selection */}
              <section>
                <div className="flex items-center gap-2 mb-4">
                  <div className="bg-blue-100 p-2 rounded-lg text-blue-600"><Navigation size={20} /></div>
                  <h3 className="text-xl font-bold text-slate-800">Travel Options</h3>
                </div>
                <div className="space-y-3">
                  {plan.transportOptions.map((option, idx) => (
                    <TransportCard 
                      key={idx} 
                      option={option} 
                      isSelected={selectedTransport?.mode === option.mode}
                      onSelect={() => setSelectedTransport(option)}
                    />
                  ))}
                </div>
              </section>

              {/* Places to Visit */}
              <section>
                <div className="flex items-center gap-2 mb-4">
                   <div className="bg-green-100 p-2 rounded-lg text-green-600"><Map size={20} /></div>
                   <h3 className="text-xl font-bold text-slate-800">Explore Nearby (100km Radius)</h3>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {plan.placesToVisit.map((place, idx) => (
                    <div key={idx} className="bg-white rounded-xl overflow-hidden border border-slate-200 shadow-sm hover:shadow-md transition-all group">
                       <div className="h-32 bg-slate-200 overflow-hidden relative">
                          <img 
                            src={`https://picsum.photos/seed/${place.name.replace(/\s/g, '')}/400/200`} 
                            alt={place.name} 
                            className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                          />
                          <div className="absolute top-2 right-2 bg-black/60 backdrop-blur-sm text-white text-xs px-2 py-1 rounded-full">
                            {place.category}
                          </div>
                       </div>
                       <div className="p-4">
                          <div className="flex justify-between items-start mb-2">
                             <h4 className="font-bold text-slate-800">{place.name}</h4>
                             <span className="text-xs text-slate-500 whitespace-nowrap">{place.distance}</span>
                          </div>
                          <p className="text-sm text-slate-500 line-clamp-2 mb-3">{place.description}</p>
                          <div className="text-xs font-semibold text-green-700">
                             Entry Estimate: ₹{place.estimatedEntryCost}
                          </div>
                       </div>
                    </div>
                  ))}
                </div>
              </section>

              {/* Stays */}
              <section>
                 <div className="flex items-center gap-2 mb-4">
                    <div className="bg-purple-100 p-2 rounded-lg text-purple-600"><Hotel size={20} /></div>
                    <h3 className="text-xl font-bold text-slate-800">Where to Stay</h3>
                 </div>
                 <div className="space-y-4">
                    {plan.stayOptions.map((stay, idx) => (
                      <div 
                        key={idx} 
                        onClick={() => setSelectedStay(stay)}
                        className={`p-4 rounded-xl border transition-all cursor-pointer flex flex-col sm:flex-row gap-4 ${
                          selectedStay?.name === stay.name ? 'border-orange-500 bg-orange-50 ring-1 ring-orange-500' : 'border-slate-200 bg-white hover:border-orange-200'
                        }`}
                      >
                         <img 
                            src={`https://picsum.photos/seed/${stay.name.replace(/\s/g, '')}hotel/150/150`}
                            alt={stay.name}
                            className="w-full sm:w-24 sm:h-24 rounded-lg object-cover"
                         />
                         <div className="flex-1">
                            <div className="flex justify-between items-start">
                               <div>
                                  <h4 className="font-bold text-slate-800">{stay.name}</h4>
                                  <p className="text-xs text-slate-500 mb-1">{stay.location} • {stay.type}</p>
                                  <div className="flex items-center gap-1">
                                     <Star size={12} className="text-yellow-400 fill-yellow-400" />
                                     <span className="text-sm font-medium">{stay.rating}</span>
                                  </div>
                               </div>
                               <div className="text-right">
                                  <span className="block text-lg font-bold text-slate-800">₹{stay.pricePerNight}</span>
                                  <span className="text-xs text-slate-400">/night</span>
                               </div>
                            </div>
                            <div className="mt-3 flex flex-wrap gap-2">
                              {stay.features.slice(0, 3).map((f, i) => (
                                <span key={i} className="text-xs px-2 py-1 bg-slate-100 text-slate-600 rounded">{f}</span>
                              ))}
                            </div>
                         </div>
                      </div>
                    ))}
                 </div>
              </section>
            </div>

            {/* Right Column: Calculator */}
            <div className="lg:col-span-1">
              <ExpenseCalculator 
                plan={plan}
                days={days}
                travelers={travelers}
                selectedTransport={selectedTransport}
                selectedStay={selectedStay}
              />
            </div>

          </div>
        )}

        {/* Placeholder for Empty State */}
        {!plan && !loading && !error && (
          <div className="text-center py-20 opacity-50">
             <Map size={64} className="mx-auto mb-4 text-slate-300" />
             <p className="text-lg text-slate-400">Enter a source and destination to start planning.</p>
          </div>
        )}

      </div>

