import { GoogleGenAI, Type, Schema } from "@google/genai";
import { TripPlan } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

const tripPlanSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    source: { type: Type.STRING },
    destination: { type: Type.STRING },
    distanceKm: { type: Type.NUMBER, description: "Approximate distance in KM" },
    bestTimeToVisit: { type: Type.STRING },
    summary: { type: Type.STRING, description: "A short, inspiring summary of the trip" },
    transportOptions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          mode: { type: Type.STRING, enum: ["Bus", "Train", "Flight", "Cab"] },
          providerName: { type: Type.STRING },
          duration: { type: Type.STRING },
          cost: { type: Type.NUMBER, description: "Cost in INR per person" },
          description: { type: Type.STRING },
        },
        required: ["mode", "cost", "duration", "providerName"],
      },
    },
    placesToVisit: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          category: { type: Type.STRING, enum: ['Historical', 'Nature', 'Religious', 'Adventure', 'Leisure', 'Hidden Gem'] },
          distance: { type: Type.STRING, description: "Distance from main city center" },
          description: { type: Type.STRING },
          estimatedEntryCost: { type: Type.NUMBER, description: "Entry fee in INR" },
        },
        required: ["name", "category", "distance"],
      },
    },
    diningOptions: {
      type: Type.ARRAY,
      description: "List of aesthetic cafes and popular local food spots",
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          cuisine: { type: Type.STRING },
          costPerPerson: { type: Type.NUMBER },
          vibe: { type: Type.STRING, description: "e.g., Rooftop, Boho, Minimalist, Traditional" },
          description: { type: Type.STRING },
          mustTryDish: { type: Type.STRING },
        },
        required: ["name", "vibe", "mustTryDish"],
      },
    },
    stayOptions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['Hotel', 'Hostel', 'Resort', 'Lodge'] },
          pricePerNight: { type: Type.NUMBER, description: "Cost in INR per night" },
          rating: { type: Type.NUMBER },
          location: { type: Type.STRING },
          features: { type: Type.ARRAY, items: { type: Type.STRING } },
        },
        required: ["name", "pricePerNight", "type"],
      },
    },
    estimatedFoodCostPerDay: { type: Type.NUMBER, description: "Average food cost per person per day in INR" },
    localTravelCostEstimate: { type: Type.NUMBER, description: "Estimated total local travel cost (cabs/autos) for the whole trip in INR" },
  },
  required: ["source", "destination", "transportOptions", "placesToVisit", "diningOptions", "stayOptions", "estimatedFoodCostPerDay"],
};

export const generateTripPlan = async (source: string, destination: string, days: number): Promise<TripPlan> => {
  if (!API_KEY) {
    throw new Error("API Key is missing. Please check your environment configuration.");
  }

  const prompt = `
    Act as an expert Indian Travel Agent & Lifestyle Guide. Plan a trip from ${source} to ${destination} for ${days} days.

    Requirements:
    1. Transport: 3-4 options (Cheapest, Fastest, Balanced).
    2. Places: 5 top tourist places + 2 "Hidden Gems" or local secrets.
    3. Food & Vibe: Suggest 4-5 specifically "Aesthetic Cafes" (Instagrammable spots) and legendary local food joints. Include their vibe (Boho, Rustic, etc.) and must-try dishes.
    4. Stays: Suggest 4 options: 1 Hostel (social vibe), 1 Budget Hotel, 1 Aesthetic/Boutique Stay, and 1 Premium Resort.
    5. Costs: Realistic INR estimates.

    Ensure the response is valid JSON matching the schema.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: tripPlanSchema,
        temperature: 0.4,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No data received from AI");

    return JSON.parse(text) as TripPlan;
  } catch (error) {
    console.error("Error generating trip plan:", error);
    throw new Error("Failed to generate trip plan. Please try again.");
  }
};

