  const [plan, setPlan] = useState<TripPlan | null>(null);
  const [error, setError] = useState<string | null>(null);

  // --- Wizard/Stepper State ---
  // Steps: 0: Input, 1: Explore(Places/Food), 2: Transport, 3: Stay, 4: Budget
  const [currentStep, setCurrentStep] = useState(0);

  // --- Selection State ---
  const [selectedTransport, setSelectedTransport] = useState<TransportOption | null>(null);
  const [selectedStay, setSelectedStay] = useState<Stay | null>(null);

  // --- Modals ---
  const [showScope, setShowScope] = useState(false);

  // --- Helpers ---
  const getPhotoUrl = (name: string, context: string) => {
    // Generates a photorealistic image URL based on the specific name of the place
    const prompt = `professional travel photography of ${name} ${context}, india, real place, 4k, architectural, interior design, daylight, highly detailed, cinematic lighting, no text`;
    return `https://image.pollinations.ai/prompt/${encodeURIComponent(prompt)}?width=800&height=600&nologo=true&seed=${Math.floor(Math.random() * 100)}`;
  };

  // --- Handlers ---
  const handleLogin = () => {
    setIsLoggedIn(true);
