export enum TransportMode {
  BUS = 'Bus',
  TRAIN = 'Train',
  FLIGHT = 'Flight',
  CAB = 'Cab'
}

export interface TransportOption {
  mode: TransportMode;
  providerName: string;
  duration: string;
  cost: number;
  description: string;
}

export interface Place {
  name: string;
  category: 'Historical' | 'Nature' | 'Religious' | 'Adventure' | 'Leisure' | 'Hidden Gem' | 'Shopping';
  distance: string;
  description: string;
  estimatedEntryCost: number;
}

export interface DiningSpot {
  name: string;
  cuisine: string;
  costPerPerson: number;
  vibe: string; // e.g., "Boho", "Rooftop", "Traditional"
  description: string;
  mustTryDish: string;
}

export interface Stay {
  name: string;
  type: 'Hotel' | 'Hostel' | 'Resort' | 'Lodge';
  pricePerNight: number;
  rating: number;
  location: string;
  features: string[];
}

export interface TripPlan {
  source: string;
  destination: string;
  distanceKm: number;
  bestTimeToVisit: string;
  transportOptions: TransportOption[];
  placesToVisit: Place[];
  diningOptions: DiningSpot[]; // New field for cafes/restaurants
  stayOptions: Stay[];
  estimatedFoodCostPerDay: number;
  localTravelCostEstimate: number;
  summary: string;
}

export interface UserInput {
  source: string;
  destination: string;
  travelers: number;
  days: number;
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { TripPlan } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

const tripPlanSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    source: { type: Type.STRING },
    destination: { type: Type.STRING },
    distanceKm: { type: Type.NUMBER, description: "Approximate distance in KM" },
    bestTimeToVisit: { type: Type.STRING },
    summary: { type: Type.STRING, description: "A short, inspiring summary of the trip" },
    transportOptions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          mode: { type: Type.STRING, enum: ["Bus", "Train", "Flight", "Cab"] },
          providerName: { type: Type.STRING },
          duration: { type: Type.STRING },
          cost: { type: Type.NUMBER, description: "Cost in INR per person" },
          description: { type: Type.STRING },
        },
        required: ["mode", "cost", "duration", "providerName"],
      },
    },
    placesToVisit: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          category: { type: Type.STRING, enum: ['Historical', 'Nature', 'Religious', 'Adventure', 'Leisure', 'Hidden Gem', 'Shopping'] },
          distance: { type: Type.STRING, description: "Distance from main city center" },
          description: { type: Type.STRING },
          estimatedEntryCost: { type: Type.NUMBER, description: "Entry fee in INR (0 if free)" },
        },
        required: ["name", "category", "distance"],
      },
    },
    diningOptions: {
      type: Type.ARRAY,
      description: "List of aesthetic cafes and popular local food spots",
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          cuisine: { type: Type.STRING },
          costPerPerson: { type: Type.NUMBER },
          vibe: { type: Type.STRING, description: "e.g., Rooftop, Boho, Minimalist, Traditional" },
          description: { type: Type.STRING },
          mustTryDish: { type: Type.STRING },
        },
        required: ["name", "vibe", "mustTryDish"],
      },
    },
    stayOptions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['Hotel', 'Hostel', 'Resort', 'Lodge'] },
          pricePerNight: { type: Type.NUMBER, description: "Cost in INR per night" },
          rating: { type: Type.NUMBER },
          location: { type: Type.STRING },
          features: { type: Type.ARRAY, items: { type: Type.STRING } },
        },
        required: ["name", "pricePerNight", "type"],
      },
    },
    estimatedFoodCostPerDay: { type: Type.NUMBER, description: "Average food cost per person per day in INR" },
    localTravelCostEstimate: { type: Type.NUMBER, description: "Estimated total local travel cost (cabs/autos) for the whole trip in INR" },
  },
  required: ["source", "destination", "transportOptions", "placesToVisit", "diningOptions", "stayOptions", "estimatedFoodCostPerDay"],
};

export const generateTripPlan = async (source: string, destination: string, days: number): Promise<TripPlan> => {
  if (!API_KEY) {
    throw new Error("API Key is missing. Please check your environment configuration.");
  }

  const prompt = `
    Act as an expert Indian Travel Agent & Lifestyle Guide. Plan a trip from ${source} to ${destination} for ${days} days.

    CRITICAL INSTRUCTION: You MUST use REAL, EXISTING names of Hotels, Cafes, and Tourist spots. Do not invent names.

    Requirements:
    1. Transport: 3-4 options (Cheapest, Fastest, Balanced).
    2. Places: Provide a COMPREHENSIVE list (Total 15-20 places). 
       - 8-10 Top Tourist Attractions (Historical, Nature, Religious).
       - 3-4 Hidden Gems/Offbeat spots.
       - 4 Best Local Markets or Shopping Streets for souvenirs/clothes (Category: 'Shopping').
       Use specific famous names.
    3. Food & Vibe: Suggest 5 specifically "Aesthetic Cafes" (Instagrammable spots) and legendary local food joints. Use REAL names (e.g. "Glenary's" or "Cafe 1947").
    4. Stays: Suggest exactly 5 accommodation options strictly sorted by price (Low to High). Use REAL hotel names:
       - Option 1: Ultra-cheap (Real Hostel/Backpacker Dorm)
       - Option 2: Budget Lodge/Hotel
       - Option 3: Mid-range/Boutique Hotel
       - Option 4: Premium/Comfort Hotel
       - Option 5: Luxury Resort/Palace (e.g., Taj, Oberoi, etc.)
    5. Costs: Realistic INR estimates.

    Ensure the response is valid JSON matching the schema.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: tripPlanSchema,
        temperature: 0.4,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No data received from AI");

    return JSON.parse(text) as TripPlan;
  } catch (error) {
    console.error("Error generating trip plan:", error);
    throw new Error("Failed to generate trip plan. Please try again.");
  }
};

import React, { useState } from 'react';
import { TripPlan, TransportOption, Stay } from './types';
import { generateTripPlan } from './services/geminiService';
import ExpenseCalculator from './components/ExpenseCalculator';
import TransportCard from './components/TransportCard';
import LoginPage from './components/LoginPage';
import { 
  MapPin, Calendar, Users, ArrowRight, Loader2, Info, Star, 
  Map, Hotel, Navigation, Coffee, Camera, CheckCircle2, ChevronRight, ChevronLeft,
  Utensils, ExternalLink, ShoppingBag
} from 'lucide-react';

const App: React.FC = () => {
  // --- Global State ---
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  // --- Search Input State ---
  const [source, setSource] = useState('');
  const [destination, setDestination] = useState('');
  const [days, setDays] = useState<number>(3);
  const [travelers, setTravelers] = useState<number>(2);

  // --- Planner Data State ---
  const [loading, setLoading] = useState(false);
  const [plan, setPlan] = useState<TripPlan | null>(null);
  const [error, setError] = useState<string | null>(null);

  // --- Wizard/Stepper State ---
  // Steps: 0: Input, 1: Explore(Places/Food), 2: Transport, 3: Stay, 4: Budget
  const [currentStep, setCurrentStep] = useState(0);

  // --- Selection State ---
  const [selectedTransport, setSelectedTransport] = useState<TransportOption | null>(null);
  const [selectedStay, setSelectedStay] = useState<Stay | null>(null);

  // --- Modals ---
  const [showScope, setShowScope] = useState(false);

  // --- Helpers ---
  const getRealPhotoUrl = (query: string) => {
    // Uses Bing's image thumbnail service to fetch a REAL photo from the web
    // This avoids AI artifacts and shows the actual place
    return `https://tse4.mm.bing.net/th?q=${encodeURIComponent(query + ' india travel')}&w=800&h=600&c=7&rs=1&p=0`;
  };

  const openInMaps = (name: string) => {
    const query = encodeURIComponent(`${name}, ${plan?.destination || 'India'}`);
    window.open(`https://www.google.com/maps/search/?api=1&query=${query}`, '_blank');
  };

  // --- Handlers ---
  const handleLogin = () => {
    setIsLoggedIn(true);
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!source || !destination) return;

    setLoading(true);
    setError(null);
    setPlan(null);

    try {
      const result = await generateTripPlan(source, destination, days);
      setPlan(result);
      // Pre-select first options
      if (result.transportOptions.length > 0) setSelectedTransport(result.transportOptions[0]);
      if (result.stayOptions.length > 0) setSelectedStay(result.stayOptions[0]);

      setCurrentStep(1); // Move to first result step
    } catch (err: any) {
      setError(err.message || "Something went wrong.");
    } finally {
      setLoading(false);
    }
  };

  const nextStep = () => setCurrentStep(prev => Math.min(prev + 1, 4));
  const prevStep = () => setCurrentStep(prev => Math.max(prev - 1, 1));

  // --- Render Functions ---

  // 1. Login View
  if (!isLoggedIn) {
    return <LoginPage onLogin={handleLogin} />;
  }

  // 2. Search View (Step 0)
  if (currentStep === 0) {
    return (
      <div className="min-h-screen bg-slate-900 text-white relative overflow-hidden">
        {/* Navbar */}
        <nav className="absolute top-0 w-full p-6 z-20 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="bg-orange-500 p-2 rounded-lg"><Navigation size={20} /></div>
            <span className="text-xl font-bold">YatraAI</span>
          </div>
          <button onClick={() => setShowScope(true)} className="text-sm hover:text-orange-400 transition-colors">Future Scope</button>
        </nav>

        {/* Hero Background */}
        <div className="absolute inset-0 bg-gradient-to-br from-indigo-900/90 to-slate-900/90 z-10" />
        <div 
          className="absolute inset-0 z-0 opacity-40"
          style={{ backgroundImage: 'url("https://images.unsplash.com/photo-1532664189809-02133fe698d3?auto=format&fit=crop&q=80")', backgroundSize: 'cover' }}
        />

        <div className="relative z-20 max-w-4xl mx-auto px-4 h-screen flex flex-col justify-center">
          <div className="text-center mb-10">
            <h1 className="text-5xl md:text-6xl font-extrabold mb-6 tracking-tight leading-tight">
