          {error && <div className="mt-4 p-3 bg-red-500/20 text-red-200 border border-red-500/50 rounded-lg text-center text-sm">{error}</div>}
        </div>

        {/* Future Scope Modal */}
        {showScope && (
          <div className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center p-4">
