import { GoogleGenAI, Type, Schema } from "@google/genai";
import { TripPlan } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

const tripPlanSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    source: { type: Type.STRING },
    destination: { type: Type.STRING },
    distanceKm: { type: Type.NUMBER, description: "Approximate distance in KM" },
    bestTimeToVisit: { type: Type.STRING },
    summary: { type: Type.STRING, description: "A short, inspiring summary of the trip" },
    transportOptions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          mode: { type: Type.STRING, enum: ["Bus", "Train", "Flight", "Cab"] },
          providerName: { type: Type.STRING },
          duration: { type: Type.STRING },
          cost: { type: Type.NUMBER, description: "Cost in INR per person" },
          description: { type: Type.STRING },
        },
        required: ["mode", "cost", "duration", "providerName"],
      },
    },
    placesToVisit: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          category: { type: Type.STRING, enum: ['Historical', 'Nature', 'Religious', 'Adventure', 'Leisure', 'Hidden Gem', 'Shopping'] },
          distance: { type: Type.STRING, description: "Distance from main city center" },
          description: { type: Type.STRING },
          estimatedEntryCost: { type: Type.NUMBER, description: "Entry fee in INR (0 if free)" },
        },
        required: ["name", "category", "distance"],
      },
    },
    diningOptions: {
      type: Type.ARRAY,
      description: "List of spots including Aesthetic Cafes (for photos/couples) AND Budget Street Food",
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          cuisine: { type: Type.STRING },
          costPerPerson: { type: Type.NUMBER, description: "Cost per person" },
          vibe: { type: Type.STRING, description: "e.g., 'Romantic/Aesthetic', 'Rooftop', 'Street Food', 'Instagrammable'" },
          description: { type: Type.STRING, description: "Highlight if good for couples or photos" },
          mustTryDish: { type: Type.STRING },
        },
        required: ["name", "vibe", "mustTryDish"],
      },
    },
    stayOptions: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['Hotel', 'Hostel', 'Resort', 'Lodge'] },
          pricePerNight: { type: Type.NUMBER, description: "Cost in INR per night" },
          rating: { type: Type.NUMBER },
          location: { type: Type.STRING },
          features: { type: Type.ARRAY, items: { type: Type.STRING } },
        },
        required: ["name", "pricePerNight", "type"],
      },
    },
    estimatedFoodCostPerDay: { type: Type.NUMBER, description: "Strictly BUDGET estimate for 3 meals (street food/dhaba prices only). Do NOT include expensive cafe costs here." },
    localTravelCostEstimate: { type: Type.NUMBER, description: "Estimated total local travel cost (cabs/autos/buses) for the whole trip in INR" },
  },
  required: ["source", "destination", "transportOptions", "placesToVisit", "diningOptions", "stayOptions", "estimatedFoodCostPerDay"],
};

export const generateTripPlan = async (source: string, destination: string, days: number): Promise<TripPlan> => {
  if (!API_KEY) {
    throw new Error("API Key is missing. Please check your environment configuration.");
  }

  const prompt = `
    Act as an expert Indian Travel Agent specializing in BUDGET BACKPACKING and COUPLE TRIPS. Plan a trip from ${source} to ${destination} for ${days} days.

    CRITICAL INSTRUCTION: You MUST use REAL, EXISTING names. 
    GOAL: Create a mix of Aesthetic experiences (for photos) and Budget living (for saving money).

    Requirements:
    1. Transport: 3-4 options. Focus on Budget trains (Sleeper/3AC) and Buses.
    2. Places: Provide a COMPREHENSIVE list (Total 15-20 places). 
       - 8-10 Top Tourist Attractions.
       - 3-4 Hidden Gems.
       - 4 Best Local Markets.
    3. Food: Suggest 5 spots. 
       - 3 spots MUST be "Aesthetic Cafes" suitable for couples and photography (Instagrammable). Mention "Perfect for couples" or "Photogenic" in description.
       - 2 spots MUST be "Legendary Street Food" for cheap eats.
    4. Stays: Suggest 5 options sorted by price (Low to High). Start with dirt-cheap hostels/dorms.
    5. Costs: 
       - Food Estimate: AGGRESSIVELY LOW. Assume the user eats street food for sustenance and only visits cafes for photos/coffee. Calculate daily cost based on street food prices (approx 500-800 INR/day). Do NOT add full cafe meal prices to the daily estimate.
       - Travel: Assume public transport.

    Ensure the response is valid JSON matching the schema.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: tripPlanSchema,
        temperature: 0.4,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No data received from AI");

    return JSON.parse(text) as TripPlan;
  } catch (error) {
    console.error("Error generating trip plan:", error);
    throw new Error("Failed to generate trip plan. Please try again.");
  }
};

import React, { useMemo } from 'react';
import { TripPlan, TransportOption, Stay } from '../types';
import { IndianRupee, PieChart, Info } from 'lucide-react';

interface ExpenseCalculatorProps {
  plan: TripPlan;
  travelers: number;
  days: number;
  selectedTransport: TransportOption | null;
  selectedStay: Stay | null;
}

const ExpenseCalculator: React.FC<ExpenseCalculatorProps> = ({ 
  plan, 
  travelers, 
  days, 
  selectedTransport, 
  selectedStay 
}) => {

  // Defaults if nothing selected (take lowest/average for initial view)
  const transportCost = selectedTransport ? selectedTransport.cost : Math.min(...plan.transportOptions.map(t => t.cost));
  const stayCost = selectedStay ? selectedStay.pricePerNight : Math.min(...plan.stayOptions.map(s => s.pricePerNight));

  const totalTransport = transportCost * travelers * 2; // Round trip
  const totalStay = stayCost * days * Math.ceil(travelers / 2); // Assuming 2 people per room
  const totalFood = plan.estimatedFoodCostPerDay * days * travelers;
  const totalLocalTravel = plan.localTravelCostEstimate;
  const buffer = 1000; // Reduced emergency buffer for budget accuracy

  const grandTotal = totalTransport + totalStay + totalFood + totalLocalTravel + buffer;

  return (
    <div className="bg-white rounded-xl shadow-lg p-6 border border-slate-100 sticky top-6">
      <div className="flex items-center gap-2 mb-4 text-orange-600">
        <PieChart size={24} />
        <h2 className="text-xl font-bold">Estimated Budget</h2>
      </div>

      <div className="space-y-3 text-sm text-slate-600">
        <div className="flex justify-between items-center">
          <span>Travel (Round Trip) <span className="text-xs bg-slate-100 px-1 rounded">x{travelers}</span></span>
          <span className="font-medium">₹{totalTransport.toLocaleString()}</span>
        </div>

        <div className="flex justify-between items-center">
          <span>Stay ({days} Nights) <span className="text-xs bg-slate-100 px-1 rounded">{Math.ceil(travelers/2)} Rooms</span></span>
          <span className="font-medium">₹{totalStay.toLocaleString()}</span>
        </div>

        <div className="flex justify-between items-center">
          <div className="flex flex-col">
            <span>Food & Drinks</span>
            <span className="text-[10px] text-slate-400 leading-tight">(Street food baseline)</span>
          </div>
          <span className="font-medium">₹{totalFood.toLocaleString()}</span>
        </div>

        <div className="flex justify-between items-center">
          <span>Local Sightseeing</span>
          <span className="font-medium">₹{totalLocalTravel.toLocaleString()}</span>
        </div>

        <div className="flex justify-between items-center text-xs text-slate-400">
          <span>Misc/Buffer</span>
          <span>₹{buffer.toLocaleString()}</span>
        </div>
      </div>

      <div className="border-t border-slate-200 my-4 pt-4">
        <div className="flex justify-between items-end">
          <span className="text-slate-500 font-medium">Total Estimate</span>
          <div className="text-right">
             <span className="text-3xl font-bold text-slate-800 block leading-none">
              ₹{grandTotal.toLocaleString()}
             </span>
             <span className="text-xs text-slate-400">approx. for whole trip</span>
          </div>
        </div>
      </div>

      <div className="mt-4 space-y-2">
        <div className="bg-orange-50 p-3 rounded-lg text-xs text-orange-700 flex gap-2">
          <Info size={14} className="shrink-0 mt-0.5" />
          <p><strong>Note:</strong> Aesthetic cafe visits are considered "extras" and are not included in this budget estimate to keep costs realistic for a budget trip.</p>
        </div>
      </div>
    </div>
  );
};

