/**
 * Robustly retrieves and sanitizes the API Key.
 * Checks for Vite, Create-React-App, and standard Node environment variables.
 */
const getSanitizedApiKey = (): string => {
  let key = '';

  // 1. Try Vite environment (import.meta.env)
  try {
    // @ts-ignore
    if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env.VITE_API_KEY) {
      // @ts-ignore
      key = import.meta.env.VITE_API_KEY;
    }
  } catch (e) {
    // Ignore errors if import.meta is not available
  }

  // 2. Try Create React App / Node environment (process.env)
  if (!key && typeof process !== 'undefined' && process.env) {
    if (process.env.REACT_APP_API_KEY) {
      key = process.env.REACT_APP_API_KEY;
    } else if (process.env.API_KEY) {
      key = process.env.API_KEY;
    }
  }

  if (!key) return '';

  // Sanitize: Trim whitespace
  key = key.trim();

  // Sanitize: Remove wrapping quotes (common mistake in .env files)
  if ((key.startsWith('"') && key.endsWith('"')) || (key.startsWith("'") && key.endsWith("'"))) {
    key = key.substring(1, key.length - 1);
  }

  return key;
};

// Initialize the API key once
const API_KEY = getSanitizedApiKey();

